// Написан autotest-writer вручную (уборка блока в finally). spec: .qa/e2e/specs/gifts.md 2.2; кейс .qa/tests/gifts/GIFT-05.
// new02 получил подарки только от new10 «בדיקה כללי» → после её блокировки список пуст. Блок снимается всегда.
// Не проверен на живой странице (кнопка «⋮» строки, /settings → «המתנות שקיבלתי») — проверить при первом /qa-regress.
import { test, expect } from '../../fixtures';
import { saveSession } from '../_shared/session';
import { N10, phone, openReceivedGifts, receivedRows, unblock } from './gifts-helpers';

test.describe('Подарки: «המתנות שקיבלתי» — блок отправителя', () => {
  test.describe.configure({ mode: 'serial', timeout: 180_000 });

  test('Блок отправителя из «⋮» → «עוד לא קיבלת מתנות»; после разблокировки строки вернулись @iphone @data (#9a50b0)', async ({ asUser }) => {
    const p = await asUser('new02');
    let blocked = false;
    try {
      await phone(p);
      await openReceivedGifts(p);
      const rows = receivedRows(p, N10);
      await expect(rows.first()).toBeVisible();

      // «⋮» у строки → «חסימת בדיקה כללי» → «לחסום» (AC 10).
      await p.getByRole('button', { name: /פעולות|⋮|⋯|more/i }).first().click();
      const menu = p.getByRole('dialog');
      await expect(menu.getByText(`פעולות על ${N10}`)).toBeVisible();
      await menu.getByRole('button', { name: new RegExp(`חסימת ${N10}`) }).click();
      const confirm = p.getByRole('dialog');
      await expect(confirm.getByText(`לחסום את ${N10}?`)).toBeVisible();
      const w = p.waitForResponse((r) => /block/i.test(r.url()) && !['GET', 'HEAD', 'OPTIONS'].includes(r.request().method()));
      blocked = true;
      await confirm.getByRole('button', { name: 'לחסום', exact: true }).click();
      expect((await w).ok(), 'запрос блокировки 2xx').toBeTruthy();

      // Пусто (AC 2, 10).
      await openReceivedGifts(p);
      await expect(p.getByText('עוד לא קיבלת מתנות')).toBeVisible();
      await expect(p.getByText(/מתנה שתקבל\/י תופיע כאן ובראש רשימת ההודעות/)).toBeVisible();
      await expect(receivedRows(p, N10)).toHaveCount(0);

      // Разблокировка → строки вернулись.
      await unblock(p, N10);
      blocked = false;
      await expect(async () => {
        await openReceivedGifts(p);
        await expect(receivedRows(p, N10).first()).toBeVisible({ timeout: 10_000 });
      }).toPass({ timeout: 60_000 });
    } finally {
      let err: unknown;
      if (blocked) await unblock(p, N10).catch((e) => (err = e));
      await saveSession(p, 'new02');
      if (err) throw new Error(`НЕ снят блок new02→new10: сними вручную (new02 → /blocked-users → ביטול חסימה ${N10}). ${err}`);
    }
  });
});
